import { T } from "@/domain/models";
import type {
  CourseStudyContent,
  KnowledgeSection,
  StudyLevel,
} from "./study-content";

const S = (
  id: string,
  level: StudyLevel,
  title: [string, string],
  lead: [string, string],
  paragraphs: [string, string][],
  bullets: [string, string][],
  rule: [string, string],
  pitfall: [string, string],
  code?: [string, string, string],
): KnowledgeSection => ({
  id,
  level,
  title: T(...title),
  lead: T(...lead),
  paragraphs: paragraphs.map((item) => T(...item)),
  bullets: bullets.map((item) => T(...item)),
  rule: T(...rule),
  pitfall: T(...pitfall),
  code: code ? { label: T(code[0], code[1]), value: code[2] } : undefined,
});

